"""
Runtime profile adapter layer with aws and onprem parity.

Defines port interfaces (abstract contracts) for object storage, queue,
eventing, secrets, and log sink. Provides concrete adapters for both
'aws' and 'onprem' profiles, and a profile-aware adapter registry
selectable via the DEPLOYMENT_PROFILE environment variable.

The adapter registry is importable as shared.adapters by downstream REQs.
Business logic must only depend on the port interfaces, never on concrete
adapter classes directly.
"""

from __future__ import annotations

import abc
import io
import os
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Protocol, runtime_checkable


# ---------------------------------------------------------------------------
# Deployment profile
# ---------------------------------------------------------------------------

class DeploymentProfile(str, Enum):
    AWS = "aws"
    ONPREM = "onprem"


def get_deployment_profile() -> DeploymentProfile:
    """Read DEPLOYMENT_PROFILE from environment. Defaults to 'onprem'."""
    raw = os.environ.get("DEPLOYMENT_PROFILE", "onprem").strip().lower()
    try:
        return DeploymentProfile(raw)
    except ValueError:
        raise ValueError(
            f"Invalid DEPLOYMENT_PROFILE='{raw}'. "
            f"Allowed values: {[p.value for p in DeploymentProfile]}"
        )


# ---------------------------------------------------------------------------
# Port interfaces (abstract contracts)
# ---------------------------------------------------------------------------

@runtime_checkable
class ObjectStoragePort(Protocol):
    """Port for object/blob storage operations."""

    def put_object(self, bucket: str, key: str, data: bytes) -> None: ...
    def get_object(self, bucket: str, key: str) -> bytes: ...
    def delete_object(self, bucket: str, key: str) -> None: ...
    def object_exists(self, bucket: str, key: str) -> bool: ...
    def ensure_bucket(self, bucket: str) -> None: ...


@runtime_checkable
class QueuePort(Protocol):
    """Port for message queue operations."""

    def send_message(self, queue_name: str, body: str, attributes: dict[str, str] | None = None) -> str: ...
    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]: ...
    def delete_message(self, queue_name: str, receipt_handle: str) -> None: ...
    def ensure_queue(self, queue_name: str) -> str: ...


@runtime_checkable
class EventingPort(Protocol):
    """Port for event/notification publishing."""

    def publish(self, topic: str, message: str, attributes: dict[str, str] | None = None) -> str: ...
    def ensure_topic(self, topic: str) -> str: ...


@runtime_checkable
class SecretsPort(Protocol):
    """Port for secrets retrieval."""

    def get_secret(self, secret_id: str) -> str: ...
    def put_secret(self, secret_id: str, value: str) -> None: ...


@runtime_checkable
class LogSinkPort(Protocol):
    """Port for structured log sink operations."""

    def emit(self, log_group: str, log_stream: str, events: list[dict[str, Any]]) -> None: ...
    def ensure_log_group(self, log_group: str) -> None: ...


# ---------------------------------------------------------------------------
# AWS adapters
# ---------------------------------------------------------------------------

class AwsObjectStorageAdapter:
    """AWS S3 object storage adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("s3", **kwargs)

    def put_object(self, bucket: str, key: str, data: bytes) -> None:
        self._client.put_object(Bucket=bucket, Key=key, Body=data)

    def get_object(self, bucket: str, key: str) -> bytes:
        response = self._client.get_object(Bucket=bucket, Key=key)
        return response["Body"].read()

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.delete_object(Bucket=bucket, Key=key)

    def object_exists(self, bucket: str, key: str) -> bool:
        try:
            self._client.head_object(Bucket=bucket, Key=key)
            return True
        except self._client.exceptions.ClientError:
            return False

    def ensure_bucket(self, bucket: str) -> None:
        try:
            self._client.head_bucket(Bucket=bucket)
        except self._client.exceptions.ClientError:
            self._client.create_bucket(Bucket=bucket)


class AwsQueueAdapter:
    """AWS SQS queue adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("sqs", **kwargs)
        self._queue_url_cache: dict[str, str] = {}

    def _get_queue_url(self, queue_name: str) -> str:
        if queue_name not in self._queue_url_cache:
            resp = self._client.get_queue_url(QueueName=queue_name)
            self._queue_url_cache[queue_name] = resp["QueueUrl"]
        return self._queue_url_cache[queue_name]

    def send_message(self, queue_name: str, body: str, attributes: dict[str, str] | None = None) -> str:
        kwargs: dict[str, Any] = {
            "QueueUrl": self._get_queue_url(queue_name),
            "MessageBody": body,
        }
        if attributes:
            kwargs["MessageAttributes"] = {
                k: {"StringValue": v, "DataType": "String"} for k, v in attributes.items()
            }
        resp = self._client.send_message(**kwargs)
        return resp["MessageId"]

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        resp = self._client.receive_message(
            QueueUrl=self._get_queue_url(queue_name),
            MaxNumberOfMessages=max_messages,
            WaitTimeSeconds=wait_seconds,
        )
        return resp.get("Messages", [])

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        self._client.delete_message(
            QueueUrl=self._get_queue_url(queue_name),
            ReceiptHandle=receipt_handle,
        )

    def ensure_queue(self, queue_name: str) -> str:
        resp = self._client.create_queue(QueueName=queue_name)
        url = resp["QueueUrl"]
        self._queue_url_cache[queue_name] = url
        return url


class AwsEventingAdapter:
    """AWS SNS eventing adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("sns", **kwargs)
        self._topic_arn_cache: dict[str, str] = {}

    def publish(self, topic: str, message: str, attributes: dict[str, str] | None = None) -> str:
        arn = self._topic_arn_cache.get(topic)
        if not arn:
            arn = self.ensure_topic(topic)
        kwargs: dict[str, Any] = {"TopicArn": arn, "Message": message}
        if attributes:
            kwargs["MessageAttributes"] = {
                k: {"StringValue": v, "DataType": "String"} for k, v in attributes.items()
            }
        resp = self._client.publish(**kwargs)
        return resp["MessageId"]

    def ensure_topic(self, topic: str) -> str:
        resp = self._client.create_topic(Name=topic)
        arn = resp["TopicArn"]
        self._topic_arn_cache[topic] = arn
        return arn


class AwsSecretsAdapter:
    """AWS Secrets Manager adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("secretsmanager", **kwargs)

    def get_secret(self, secret_id: str) -> str:
        resp = self._client.get_secret_value(SecretId=secret_id)
        return resp["SecretString"]

    def put_secret(self, secret_id: str, value: str) -> None:
        try:
            self._client.create_secret(Name=secret_id, SecretString=value)
        except self._client.exceptions.ResourceExistsException:
            self._client.put_secret_value(SecretId=secret_id, SecretString=value)


class AwsLogSinkAdapter:
    """AWS CloudWatch Logs adapter (uses boto3)."""

    def __init__(self, endpoint_url: str | None = None, region_name: str = "us-east-1") -> None:
        import boto3
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        self._client = boto3.client("logs", **kwargs)

    def emit(self, log_group: str, log_stream: str, events: list[dict[str, Any]]) -> None:
        try:
            self._client.create_log_stream(logGroupName=log_group, logStreamName=log_stream)
        except self._client.exceptions.ResourceAlreadyExistsException:
            pass
        import time
        log_events = [
            {"timestamp": int(time.time() * 1000), "message": str(e)}
            for e in events
        ]
        self._client.put_log_events(
            logGroupName=log_group,
            logStreamName=log_stream,
            logEvents=log_events,
        )

    def ensure_log_group(self, log_group: str) -> None:
        try:
            self._client.create_log_group(logGroupName=log_group)
        except self._client.exceptions.ResourceAlreadyExistsException:
            pass


# ---------------------------------------------------------------------------
# On-prem adapters
# ---------------------------------------------------------------------------

class OnpremObjectStorageAdapter:
    """On-prem object storage adapter backed by MinIO (S3-compatible API)."""

    def __init__(
        self,
        endpoint_url: str | None = None,
        access_key: str | None = None,
        secret_key: str | None = None,
    ) -> None:
        from minio import Minio
        from urllib.parse import urlparse

        endpoint_url = endpoint_url or os.environ.get("MINIO_ENDPOINT", "http://localhost:9000")
        access_key = access_key or os.environ.get("MINIO_ACCESS_KEY", "minioadmin")
        secret_key = secret_key or os.environ.get("MINIO_SECRET_KEY", "minioadmin")

        parsed = urlparse(endpoint_url)
        host = parsed.netloc or parsed.path
        secure = parsed.scheme == "https"

        self._client = Minio(
            host,
            access_key=access_key,
            secret_key=secret_key,
            secure=secure,
        )

    def put_object(self, bucket: str, key: str, data: bytes) -> None:
        self._client.put_object(bucket, key, io.BytesIO(data), length=len(data))

    def get_object(self, bucket: str, key: str) -> bytes:
        response = self._client.get_object(bucket, key)
        try:
            return response.read()
        finally:
            response.close()
            response.release_conn()

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.remove_object(bucket, key)

    def object_exists(self, bucket: str, key: str) -> bool:
        try:
            self._client.stat_object(bucket, key)
            return True
        except Exception:
            return False

    def ensure_bucket(self, bucket: str) -> None:
        if not self._client.bucket_exists(bucket):
            self._client.make_bucket(bucket)


class OnpremQueueAdapter:
    """On-prem queue adapter backed by Redis lists (lightweight message queue)."""

    def __init__(self, redis_url: str | None = None) -> None:
        import redis as redis_lib
        redis_url = redis_url or os.environ.get("REDIS_URL", "redis://localhost:6379/0")
        self._client = redis_lib.Redis.from_url(redis_url, decode_responses=True)

    def send_message(self, queue_name: str, body: str, attributes: dict[str, str] | None = None) -> str:
        import json
        import uuid
        msg_id = str(uuid.uuid4())
        envelope = json.dumps({"MessageId": msg_id, "Body": body, "Attributes": attributes or {}})
        self._client.rpush(queue_name, envelope)
        return msg_id

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        import json
        messages: list[dict[str, Any]] = []
        for _ in range(max_messages):
            if wait_seconds > 0:
                item = self._client.blpop(queue_name, timeout=wait_seconds)
                raw = item[1] if item else None
            else:
                raw = self._client.lpop(queue_name)
            if raw is None:
                break
            envelope = json.loads(raw)
            envelope["ReceiptHandle"] = envelope["MessageId"]
            messages.append(envelope)
        return messages

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        # In Redis-list model, message is already removed on receive.
        pass

    def ensure_queue(self, queue_name: str) -> str:
        # Redis lists are created implicitly.
        return queue_name


class OnpremEventingAdapter:
    """On-prem eventing adapter backed by Redis Pub/Sub."""

    def __init__(self, redis_url: str | None = None) -> None:
        import redis as redis_lib
        redis_url = redis_url or os.environ.get("REDIS_URL", "redis://localhost:6379/0")
        self._client = redis_lib.Redis.from_url(redis_url, decode_responses=True)

    def publish(self, topic: str, message: str, attributes: dict[str, str] | None = None) -> str:
        import json
        import uuid
        msg_id = str(uuid.uuid4())
        envelope = json.dumps({"MessageId": msg_id, "Message": message, "Attributes": attributes or {}})
        self._client.publish(topic, envelope)
        return msg_id

    def ensure_topic(self, topic: str) -> str:
        # Redis Pub/Sub topics are implicit.
        return topic


class OnpremSecretsAdapter:
    """On-prem secrets adapter backed by environment variables or a local JSON file."""

    def __init__(self, secrets_file: str | None = None) -> None:
        import json
        self._secrets_file = secrets_file or os.environ.get("SECRETS_FILE", "")
        self._store: dict[str, str] = {}
        if self._secrets_file and os.path.isfile(self._secrets_file):
            with open(self._secrets_file, "r") as f:
                self._store = json.load(f)

    def get_secret(self, secret_id: str) -> str:
        # Prefer env var, then file store
        val = os.environ.get(secret_id)
        if val is not None:
            return val
        if secret_id in self._store:
            return self._store[secret_id]
        raise KeyError(f"Secret '{secret_id}' not found in environment or secrets file.")

    def put_secret(self, secret_id: str, value: str) -> None:
        import json
        self._store[secret_id] = value
        if self._secrets_file:
            with open(self._secrets_file, "w") as f:
                json.dump(self._store, f)


class OnpremLogSinkAdapter:
    """On-prem log sink adapter that writes structured logs to local files."""

    def __init__(self, log_dir: str | None = None) -> None:
        self._log_dir = log_dir or os.environ.get("LOG_SINK_DIR", "/tmp/logs")
        os.makedirs(self._log_dir, exist_ok=True)

    def emit(self, log_group: str, log_stream: str, events: list[dict[str, Any]]) -> None:
        import json
        import time
        group_dir = os.path.join(self._log_dir, log_group)
        os.makedirs(group_dir, exist_ok=True)
        filepath = os.path.join(group_dir, f"{log_stream}.jsonl")
        with open(filepath, "a") as f:
            for event in events:
                record = {"timestamp": time.time(), "event": event}
                f.write(json.dumps(record) + "\n")

    def ensure_log_group(self, log_group: str) -> None:
        group_dir = os.path.join(self._log_dir, log_group)
        os.makedirs(group_dir, exist_ok=True)


# ---------------------------------------------------------------------------
# Adapter registry
# ---------------------------------------------------------------------------

@dataclass
class AdapterConfig:
    """Optional overrides for adapter construction."""
    # AWS / LocalStack
    aws_endpoint_url: str | None = field(default=None)
    aws_region: str = field(default="us-east-1")
    # MinIO
    minio_endpoint: str | None = field(default=None)
    minio_access_key: str | None = field(default=None)
    minio_secret_key: str | None = field(default=None)
    # Redis
    redis_url: str | None = field(default=None)
    # Secrets file
    secrets_file: str | None = field(default=None)
    # Log dir
    log_dir: str | None = field(default=None)


@dataclass(frozen=True)
class AdapterRegistry:
    """
    Immutable registry of profile-selected adapters.

    Importable as shared.adapters by downstream REQs.
    Business logic depends only on port interfaces, never on this registry's
    concrete adapter types.
    """
    object_storage: ObjectStoragePort
    queue: QueuePort
    eventing: EventingPort
    secrets: SecretsPort
    log_sink: LogSinkPort
    profile: DeploymentProfile


def _build_aws_registry(config: AdapterConfig) -> AdapterRegistry:
    endpoint = config.aws_endpoint_url or os.environ.get("AWS_ENDPOINT_URL")
    region = config.aws_region or os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
    return AdapterRegistry(
        object_storage=AwsObjectStorageAdapter(endpoint_url=endpoint, region_name=region),
        queue=AwsQueueAdapter(endpoint_url=endpoint, region_name=region),
        eventing=AwsEventingAdapter(endpoint_url=endpoint, region_name=region),
        secrets=AwsSecretsAdapter(endpoint_url=endpoint, region_name=region),
        log_sink=AwsLogSinkAdapter(endpoint_url=endpoint, region_name=region),
        profile=DeploymentProfile.AWS,
    )


def _build_onprem_registry(config: AdapterConfig) -> AdapterRegistry:
    return AdapterRegistry(
        object_storage=OnpremObjectStorageAdapter(
            endpoint_url=config.minio_endpoint,
            access_key=config.minio_access_key,
            secret_key=config.minio_secret_key,
        ),
        queue=OnpremQueueAdapter(redis_url=config.redis_url),
        eventing=OnpremEventingAdapter(redis_url=config.redis_url),
        secrets=OnpremSecretsAdapter(secrets_file=config.secrets_file),
        log_sink=OnpremLogSinkAdapter(log_dir=config.log_dir),
        profile=DeploymentProfile.ONPREM,
    )


_BUILDERS: dict[DeploymentProfile, Any] = {
    DeploymentProfile.AWS: _build_aws_registry,
    DeploymentProfile.ONPREM: _build_onprem_registry,
}


def build_adapter_registry(config: AdapterConfig | None = None) -> AdapterRegistry:
    """
    Build an AdapterRegistry for the current DEPLOYMENT_PROFILE.

    This is the single entry point for adapter construction.
    Business code calls this once at startup and passes the registry
    (or individual ports) via dependency injection.
    """
    profile = get_deployment_profile()
    cfg = config or AdapterConfig()
    builder = _BUILDERS[profile]
    return builder(cfg)


# ---------------------------------------------------------------------------
# Parity validation
# ---------------------------------------------------------------------------

_REQUIRED_PORTS = [
    ("object_storage", ObjectStoragePort),
    ("queue", QueuePort),
    ("eventing", EventingPort),
    ("secrets", SecretsPort),
    ("log_sink", LogSinkPort),
]


def validate_registry_parity(registry: AdapterRegistry) -> list[str]:
    """
    Validate that every adapter in the registry satisfies its port interface.
    Returns a list of violation descriptions (empty means valid).
    """
    violations: list[str] = []
    for attr_name, port_type in _REQUIRED_PORTS:
        adapter = getattr(registry, attr_name, None)
        if adapter is None:
            violations.append(f"Missing adapter for port '{attr_name}'")
        elif not isinstance(adapter, port_type):
            violations.append(
                f"Adapter '{attr_name}' ({type(adapter).__name__}) "
                f"does not satisfy {port_type.__name__}"
            )
    return violations

