"""
shared.adapters entry point.

Downstream REQs import this module to obtain the adapter registry:

    from feature.shared_adapters import get_registry, AdapterRegistry

Or, when promoted to canonical paths:

    from shared.adapters import get_registry, AdapterRegistry
"""

from __future__ import annotations

from feature.adapter_contract import (
    AdapterConfig,
    AdapterRegistry,
    DeploymentProfile,
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
    build_adapter_registry,
    get_deployment_profile,
    validate_registry_parity,
)

__all__ = [
    "AdapterConfig",
    "AdapterRegistry",
    "DeploymentProfile",
    "EventingPort",
    "LogSinkPort",
    "ObjectStoragePort",
    "QueuePort",
    "SecretsPort",
    "build_adapter_registry",
    "get_deployment_profile",
    "get_registry",
    "validate_registry_parity",
]

_SINGLETON: AdapterRegistry | None = None


def get_registry(config: AdapterConfig | None = None) -> AdapterRegistry:
    """
    Return a lazily-initialized singleton AdapterRegistry.

    Thread-safe for typical single-process Python apps (GIL).
    For multi-process deployments each process gets its own singleton.
    """
    global _SINGLETON
    if _SINGLETON is None:
        _SINGLETON = build_adapter_registry(config)
    return _SINGLETON


def reset_registry() -> None:
    """Reset the singleton (useful in tests)."""
    global _SINGLETON
    _SINGLETON = None

