def _unique(prefix: str = "test") -> str:
    return f"{prefix}-{uuid.uuid4().hex[:8]}"


# ---------------------------------------------------------------------------
# 1. Unit tests — profile selection
# ---------------------------------------------------------------------------

class TestDeploymentProfile:
    def test_default_profile_is_onprem(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.delenv("DEPLOYMENT_PROFILE", raising=False)
        assert get_deployment_profile() == DeploymentProfile.ONPREM

    def test_aws_profile(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.setenv("DEPLOYMENT_PROFILE", "aws")
        assert get_deployment_profile() == DeploymentProfile.AWS

    def test_onprem_profile(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.setenv("DEPLOYMENT_PROFILE", "onprem")
        assert get_deployment_profile() == DeploymentProfile.ONPREM

    def test_case_insensitive(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.setenv("DEPLOYMENT_PROFILE", "AWS")
        assert get_deployment_profile() == DeploymentProfile.AWS

    def test_invalid_profile_raises(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.setenv("DEPLOYMENT_PROFILE", "gcp")
        with pytest.raises(ValueError, match="Invalid DEPLOYMENT_PROFILE"):
            get_deployment_profile()

    def test_whitespace_trimmed(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.setenv("DEPLOYMENT_PROFILE", "  aws  ")
        assert get_deployment_profile() == DeploymentProfile.AWS


