class TestPortConformance:
    """Verify that every concrete adapter satisfies its runtime-checkable port."""

    def test_aws_object_storage_satisfies_port(self) -> None:
        # Structural check — we verify the class has the right methods
        assert issubclass(AwsObjectStorageAdapter, ObjectStoragePort)  # type: ignore[arg-type]

    def test_onprem_object_storage_satisfies_port(self) -> None:
        assert issubclass(OnpremObjectStorageAdapter, ObjectStoragePort)  # type: ignore[arg-type]

    def test_aws_queue_satisfies_port(self) -> None:
        assert issubclass(AwsQueueAdapter, QueuePort)  # type: ignore[arg-type]

    def test_onprem_queue_satisfies_port(self) -> None:
        assert issubclass(OnpremQueueAdapter, QueuePort)  # type: ignore[arg-type]

    def test_aws_eventing_satisfies_port(self) -> None:
